      "member_ids": ["4fb401f3ca86d7e2303a", "b6aa6b60dc280f699747"],
      "operation": "Streaming compression through ZSTD_compressStream2 and block compressor dispatch",
      "condition": "FUZZ_randomCParams selects a strategy whose compressor may be excluded by the build",
      "capability": "ZSTD_adjustCParams_internal and compressor dispatch resolve the strategy to a callable included compressor",
      "consequence": "Compression fails or the streaming round trip is not preserved",
      "equivalence_reason": "Both describe the same selected-strategy dispatch requirement under build exclusions."
    },
    {
      "member_ids": ["078219e3c8afa5dc95ae", "ce8a2495ff126b58ecfc"],
      "operation": "Dictionary-loaded streaming compression and decompression",
      "condition": "A valid dictionary is supplied for a streaming round trip",
      "capability": "ZSTD_CCtx_loadDictionary or ZSTD_CCtx_refCDict reaches ZSTD_loadDictionaryContent and dictionary-aware compressor selection; decompression uses the corresponding dictionary",
      "consequence": "The dictionary-backed round trip cannot be reached or completed",
      "equivalence_reason": "Both concern access to dictionary-mode compression and its matching round trip through the streaming target."
    },
    {
      "member_ids": ["987d3c7a41f5b5c7a4da"],
      "operation": "Streaming compression with a loaded dictionary",
      "condition": "A dictionary is loaded through a supported compression-context setup",
      "capability": "ZSTD_CCtx_loadDictionary or ZSTD_CCtx_refCDict reaches ZSTD_CCtx_init_compressStream2 and ZSTD_selectBlockCompressor",
      "consequence": "Dictionary-loaded streaming compression is unreachable",
      "equivalence_reason": "Kept separate because this hypothesis states compression reachability without the matching decompression and round-trip consequence."
    },
    {
      "member_ids": ["230b08efc58f6dc3ed66"],
      "operation": "Streaming compression with a window or hash log above 15",
      "condition": "The build and valid parameters support a distinct setting above the target's cap",
      "capability": "The parameter generator can reach supported ZSTD_WINDOWLOG_MAX or ZSTD_HASHLOG_MAX settings, and ZSTD_adjustCParams_internal applies them",
      "consequence": "That supported compression configuration remains unexercised",
      "equivalence_reason": "No other candidate concerns reachability of high window or hash log settings."
    }
  ]
}
